    }
    function handleClusterTestProcess() {
        setConnTest(false)
        setModalMessage("")
        dispatch(setClusterStatus({ name, host, port, scheme, username, password })).then(status => {
            if (!status['connection']) {
                setConnTest(false)
                setModalMessage("연결 실패")
