                                        onClick={() => setOpenRemoveModal(false)}
                                        variant="contained"
                                >
                                    취소
                                </Button>
                            </Box>
                        </Grid>
                    </Grid>
                </DialogActions>
            </Dialog>



        </React.Fragment>
    );
}

export default connect(store => ({ ...store.clusterReducers, ...store.dsearchReducers }))(Cluster);
"}

